$_MODULE['<{retractationcommande}prestashop>formulaire_8e768a03b00a269f26e6cb5a6213b24f'] = 'Actualmente ninguno de sus pedidos puede acogerse al desistimiento (plazo legal vencido o pedidos no afectados).';
$_MODULE['<{retractationcommande}prestashop>formulaire_c1ce181667f69ea149cb0a425ccdb21e'] = 'Actualmente ninguno de sus pedidos puede devolverse (plazo vencido o pedidos no afectados).';
$_MODULE['<{retractationcommande}prestashop>formulaire_24eabc929ddb3eb38fd6cf81b5ffa805'] = 'Introduzca la dirección de correo electrónico utilizada en el pedido y la referencia del pedido (que figura en su correo de confirmación).';
$_MODULE['<{retractationcommande}prestashop>formulaire_b414b1464d384d5b827c361fec76cc8f'] = 'Este pedido no puede (o ya no puede) acogerse al desistimiento en línea: plazo legal vencido, solicitud ya presentada o pedido no afectado. Para cualquier consulta, póngase en contacto con nuestro servicio de atención al cliente.';
$_MODULE['<{retractationcommande}prestashop>formulaire_dbad83ecebaf719a4dd60e45bbec0e03'] = 'El derecho de desistimiento no se aplica a determinados contratos (art. L221-28 del Código de consumo francés: bienes confeccionados a medida o personalizados, bienes perecederos, bienes desprecintados por razones de higiene, etc.). Una vez presentada, su solicitud es revisada por nuestro servicio de atención al cliente, que le envía el procedimiento de devolución. El reembolso se efectúa a más tardar 14 días después de la recuperación del bien o de la recepción de la prueba de envío, por el mismo medio de pago. Los gastos de devolución corren a su cargo.';
$_MODULE['<{retractationcommande}prestashop>modal_30e7d78f70861e0332aa4cbb81a2fcd3'] = 'Devolución posible';
