$_MODULE['<{retractationcommande}prestashop>modal_217c9acbe7666448db6b898ca2ab6bef'] = 'Confirmar la solicitud de devolución';
$_MODULE['<{retractationcommande}prestashop>modal_810a3d382ec684c35146d332e396e1c1'] = 'Al confirmar, su solicitud de desistimiento se transmite a nuestro servicio de atención al cliente y recibirá un acuse de recibo por correo electrónico con una copia en PDF (art. L221-21 del Código de consumo francés). Tras la comprobación de los requisitos (plazo legal, exclusiones del art. L221-28), le comunicaremos el procedimiento de devolución; le rogamos que no devuelva los productos antes de haberlo recibido. El reembolso se efectúa a más tardar 14 días después de la recuperación del bien o de la recepción de la prueba de envío (gastos de entrega incluidos en caso de desistimiento total, a prorrata en los demás casos). Los gastos de devolución corren a su cargo.';
$_MODULE['<{retractationcommande}prestashop>modal_abeaaec30c11df72742faf07dc857200'] = 'Al confirmar, su solicitud de desistimiento se transmite a nuestro servicio de atención al cliente y recibirá un acuse de recibo por correo electrónico con una copia en PDF (art. L221-21 del Código de consumo francés). Dado que su pedido ya ha sido enviado, puede rechazar el paquete en el momento de la entrega; si lo recibe, no lo abra y siga el procedimiento de devolución que le enviará nuestro servicio de atención al cliente. El reembolso se efectúa a más tardar 14 días después de la recuperación del bien o de la recepción de la prueba de su devolución. Los gastos de devolución corren a su cargo.';
$_MODULE['<{retractationcommande}prestashop>modal_ad52dcb5592e9f635028ab04aaf1fcec'] = 'Al confirmar, su solicitud de desistimiento se transmite a nuestro servicio de atención al cliente y recibirá un acuse de recibo por correo electrónico con una copia en PDF (art. L221-21 del Código de consumo francés). Dado que su pedido aún no ha sido enviado, no será necesaria ninguna devolución de producto: tras la comprobación (exclusiones del art. L221-28), se cancelará el envío y se le reembolsará la totalidad de las cantidades abonadas a más tardar 14 días después de su solicitud, por el mismo medio de pago.';
$_MODULE['<{retractationcommande}prestashop>modal_c729999c38ef8dd3345cdcab0b29495a'] = 'Al confirmar, su solicitud de devolución se transmite a nuestro servicio de atención al cliente, que la revisa según nuestras condiciones de devolución y le comunica el procedimiento a seguir. Le rogamos que no devuelva los productos antes de haberlo recibido.';
$_MODULE['<{retractationcommande}prestashop>order-detail_5d6cad579ad55412b4c2f0e3e412a87a'] = 'Dispone de un plazo legal de 14 días para desistir';
